import { ClientMetadata, ClientDataMap, ClientTransport, ClientStreamRequest } from '@anvia/client';
import { UseChatResult } from '@anvia/react';
import { ReactNode, ReactElement } from 'react';

type JsonPrimitive = string | number | boolean | null;
/** Any JSON-compatible value: primitives, objects, or readonly arrays of JSON values. */
type JsonValue = JsonPrimitive | JsonObject | readonly JsonValue[];
type JsonObject = {
    [key: string]: JsonValue;
};
/** Answer to one question asked by a tool suspended on a human interaction. */
type ToolQuestionAnswer = Readonly<{
    questionId: string;
    value: string;
}>;

type AgentQuestionChoice = Readonly<{
    label: string;
    value: string;
}>;
type AgentQuestionPrompt = Readonly<{
    id: string;
    text: string;
    choices?: readonly AgentQuestionChoice[];
    allowCustom?: boolean;
}>;
type AgentQuestionAnswer = ToolQuestionAnswer;
type AgentInteractionRequestBase = Readonly<{
    id: string;
    toolName: string;
    toolCallId: string;
    callId?: string;
    internalCallId: string;
}>;
type AgentToolApprovalRequest = AgentInteractionRequestBase & Readonly<{
    type: "tool-approval";
    input: JsonValue;
    reason?: string;
}>;
type AgentToolQuestionRequest = AgentInteractionRequestBase & Readonly<{
    type: "tool-question";
    questions: readonly AgentQuestionPrompt[];
}>;
type AgentInteractionRequest = AgentToolApprovalRequest | AgentToolQuestionRequest;

type ChatController<Metadata extends ClientMetadata = ClientMetadata, Data extends ClientDataMap = ClientDataMap> = UseChatResult<ClientTransport<ClientStreamRequest, Data, Metadata>>;
type ChatProviderProps<Metadata extends ClientMetadata = ClientMetadata, Data extends ClientDataMap = ClientDataMap> = {
    controller: ChatController<Metadata, Data>;
    children?: ReactNode;
};
declare function ChatProvider<Metadata extends ClientMetadata = ClientMetadata, Data extends ClientDataMap = ClientDataMap>({ controller, children }: ChatProviderProps<Metadata, Data>): ReactElement;
declare function useChatContext<Metadata extends ClientMetadata = ClientMetadata, Data extends ClientDataMap = ClientDataMap>(): ChatController<Metadata, Data>;
declare function useHumanInput(): {
    approvals: {
        all: (Readonly<{
            request: AgentInteractionRequest;
            runId: string;
            status: "pending" | "responded" | "cancelled";
        }> & {
            request: AgentToolApprovalRequest;
        })[];
        pending: (Readonly<{
            request: AgentInteractionRequest;
            runId: string;
            status: "pending" | "responded" | "cancelled";
        }> & {
            request: AgentToolApprovalRequest;
        })[];
    };
    questions: {
        all: (Readonly<{
            request: AgentInteractionRequest;
            runId: string;
            status: "pending" | "responded" | "cancelled";
        }> & {
            request: AgentToolQuestionRequest;
        })[];
        pending: (Readonly<{
            request: AgentInteractionRequest;
            runId: string;
            status: "pending" | "responded" | "cancelled";
        }> & {
            request: AgentToolQuestionRequest;
        })[];
    };
};

export { type AgentToolApprovalRequest as A, type ChatController as C, ChatProvider as a, type ChatProviderProps as b, useHumanInput as c, type AgentToolQuestionRequest as d, type AgentQuestionAnswer as e, type AgentQuestionPrompt as f, useChatContext as u };
